import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_counts_none_in_denominator():
    assert conversion_rate([{"converted": None}, {"converted": True}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_pooled_rate_weights_sessions():
    groups = {"a": [{"converted": True}], "b": [{"converted": False}] * 3, "c": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"c": []}) == 0.0


@pytest.mark.parametrize(('days', 'total'), [(0, 0), (2, 7), (10, 8)])
def test_trailing_window(days, total):
    assert conversions_in_window([1, 3, 4], days) == total


def test_parse_skips_comments_and_trims_fields():
    assert parse_session_log(['', '  ', '  #skip', ' x , 1 , 0 ', 'y,2, ']) == [
        {"id": 'x', "day": 1, "converted": False},
        {"id": 'y', "day": 2, "converted": None},
    ]


@pytest.mark.parametrize('line', ['x,1', 'x,1,1,0', 'x,two,1'])
def test_parse_errors_count_skipped_lines(line):
    with pytest.raises(ValueError, match=r'line 3\b'):
        parse_session_log(['# skip', '', line])


def test_dedupe_last_id_wins_before_sorting():
    events = parse_session_log(['x,5,0', 'y,2,1', 'z,1,0', 'x,2,1'])
    assert dedupe_sessions(events) == [events[2], events[3], events[1]]


def test_daily_counts_include_only_days_in_range():
    events = parse_session_log(['x,0,1', 'y,3,1', 'z,3,1', 'w,4,1'])
    assert daily_conversion_counts(events, 1, 3) == [0, 0, 2]
    assert daily_conversion_counts(events, 3, 1) == []


def test_summary_uses_calendar_window_and_nonempty_groups():
    groups = {'a': parse_session_log(['x,1,1']), 'b': parse_session_log(['y,1,1', 'z,4,0']), 'c': []}
    assert campaign_summary(groups, 2) == {'rate': 0.667, 'recent': 0, 'groups': 2}
    assert campaign_summary({}, 2) == {'rate': 0.0, 'recent': 0, 'groups': 0}


def test_group_rankings_and_rates():
    groups = {'z': [{'converted': True}], 'empty': [], 'a': [{'converted': False}], 'b': [{'converted': True}]}
    assert top_converting_groups(groups, 2) == ['b', 'z']
    assert top_converting_groups(groups, 5) == ['b', 'z', 'a']
    assert list(conversion_rate_by_group(groups).items()) == [('a', 0.0), ('b', 1.0), ('empty', None), ('z', 1.0)]


def test_conversion_streak_resets_on_nonpositive_days():
    assert longest_conversion_streak([1, 2, -1, 3, 0, 1]) == 2
    assert longest_conversion_streak([]) == 0
